#[cfg(test)]
mod tests {
    use super::*;
    use crate::sha256::hex_digest;

    /// SHA-256 (lowercase hex) of the generator output: each range as `    (0x{lo:04X}, 0x{hi:04X}),`
    /// followed by a newline. Regenerate with the script above and `shasum -a 256` to verify.
    const PY_DIGIT_RANGES_SHA256: &str =
        "5890bb56ea5ab4b44eeb3d5938635e847a58fc6a7abb318c11ac1cecbe14680f";

    #[test]
    fn test_digit_table_content_matches_pinned_digest() {
        let mut generated = String::new();
        for &(lo, hi) in PY_DIGIT_RANGES {
            generated.push_str(&format!("    (0x{lo:04X}, 0x{hi:04X}),\n"));
        }
        assert_eq!(hex_digest(generated.as_bytes()), PY_DIGIT_RANGES_SHA256);
    }

    #[test]
    fn test_digit_table_shape_is_pinned() {
        assert_eq!(PY_DIGIT_RANGES.len(), 71);
        let code_points: u32 = PY_DIGIT_RANGES.iter().map(|&(lo, hi)| hi - lo + 1).sum();
        assert_eq!(code_points, 760);
        for pair in PY_DIGIT_RANGES.windows(2) {
            assert!(pair[0].1 < pair[1].0, "ranges must be sorted and disjoint");
        }
    }
}
